{"command":"mkdir -p /workspace && cd /workspace && cat > fh_header.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"net"
	"os"
)

var (
	errNeedMore            = errors.New("need more data: cannot find trailing lf")
	errSmallBuffer         = errors.New("small read buffer. Increase ReadBufferSize")
	errEmptyInt            = errors.New("empty integer")
	errUnexpectedFirstChar = errors.New("unexpected first char found. Expecting 0-9")
	errTooLongInt          = errors.New("too long int")
	errEmptyHexNum         = errors.New("empty hex number")
	errTooLargeHexNum      = errors.New("too large hex number")
	errBodyTooLarge        = errors.New("body size exceeds the given limit")
	errTimeout             = errors.New("timeout")
	errConnectionClosed    = errors.New("the server closed connection before returning the first response byte. " +
		"Make sure the server returns 'Connection: close' response header before closing the connection")
)

type headerKV struct {
	key   string
	value string
}

type responseHeader struct {
	statusCode      int
	noHTTP11        bool
	contentLength   int // -1: chunked, -2: identity
	contentType     string
	contentEncoding string
	connectionClose bool
	headers         []headerKV
	cookies         []string
}

func (h *responseHeader) StatusCode() int {
	if h.statusCode == 0 {
		return 200
	}
	return h.statusCode
}

func (h *responseHeader) ContentType() string {
	if h.contentType == "" {
		return "text/plain; charset=utf-8"
	}
	return h.contentType
}

func (h *responseHeader) Peek(key string) string {
	k := normalizeHeaderKeyString(key)
	switch k {
	case "Content-Type":
		return h.ContentType()
	case "Content-Encoding":
		return h.contentEncoding
	case "Set-Cookie":
		return joinStrings(h.cookies, "; ")
	}
	for _, kv := range h.headers {
		if kv.key == k {
			return kv.value
		}
	}
	return ""
}

func joinStrings(ss []string, sep string) string {
	var b bytes.Buffer
	for i, s := range ss {
		if i > 0 {
			b.WriteString(sep)
		}
		b.WriteString(s)
	}
	return b.String()
}

func (h *responseHeader) mustSkipBody() bool {
	c := h.StatusCode()
	return (c >= 100 && c < 200) || c == 204 || c == 304
}

// readResponseHeader emulates the header reading loop.
func readResponseHeader(h *responseHeader, r *bufio.Reader) error {
	n := 1
	for {
		err := tryReadResponseHeader(h, r, n)
		if err == nil {
			return nil
		}
		if err != errNeedMore {
			return err
		}
		n = r.Buffered() + 1
	}
}

func isTimeoutErr(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, os.ErrDeadlineExceeded) {
		return true
	}
	var ne net.Error
	if errors.As(err, &ne) && ne.Timeout() {
		return true
	}
	return false
}

func tryReadResponseHeader(h *responseHeader, r *bufio.Reader, n int) error {
	*h = responseHeader{}
	b, err := r.Peek(n)
	if len(b) == 0 {
		if isTimeoutErr(err) {
			return errTimeout
		}
		if n == 1 || err == io.EOF {
			return io.EOF
		}
		if err == bufio.ErrBufferFull {
			return fmt.Errorf("error when reading response headers: %w", errSmallBuffer)
		}
		return fmt.Errorf("error when reading response headers: %w", err)
	}
	b, _ = r.Peek(r.Buffered())
	headersLen, errParse := parseResponseHeader(h, b)
	if errParse != nil {
		return headerError(err, errParse, b)
	}
	r.Discard(headersLen)
	return nil
}

func headerError(err, errParse error, b []byte) error {
	if errParse != errNeedMore {
		return headerErrorMsg(errParse, b)
	}
	if err == nil {
		return errNeedMore
	}
	if isOnlyCRLF(b) {
		return io.EOF
	}
	if isTimeoutErr(err) {
		return errTimeout
	}
	if err != bufio.ErrBufferFull {
		return headerErrorMsg(err, b)
	}
	return headerErrorMsg(errSmallBuffer, b)
}

func headerErrorMsg(err error, b []byte) error {
	return fmt.Errorf("error when reading response headers: %w. Buffer size=%d, contents: %s", err, len(b), bufferSnippet(b))
}

func bufferSnippet(b []byte) string {
	n := len(b)
	start := 200
	end := n - start
	if start >= end {
		start = n
		end = n
	}
	bStart, bEnd := b[:start], b[end:]
	if len(bEnd) == 0 {
		return fmt.Sprintf("%q", b)
	}
	return fmt.Sprintf("%q...%q", bStart, bEnd)
}

func isOnlyCRLF(b []byte) bool {
	for _, c := range b {
		if c != '\r' && c != '\n' {
			return false
		}
	}
	return true
}

func nextLine(b []byte) ([]byte, []byte, error) {
	nNext := bytes.IndexByte(b, '\n')
	if nNext < 0 {
		return nil, nil, errNeedMore
	}
	n := nNext
	if n > 0 && b[n-1] == '\r' {
		n--
	}
	return b[:n], b[nNext+1:], nil
}

func parseResponseHeader(h *responseHeader, buf []byte) (int, error) {
	m, err := parseFirstLine(h, buf)
	if err != nil {
		return 0, err
	}
	n, err := parseHeaders(h, buf[m:])
	if err != nil {
		return 0, err
	}
	return m + n, nil
}

func parseFirstLine(h *responseHeader, buf []byte) (int, error) {
	bNext := buf
	var b []byte
	var err error
	for len(b) == 0 {
		if b, bNext, err = nextLine(bNext); err != nil {
			return 0, err
		}
	}
	n := bytes.IndexByte(b, ' ')
	if n < 0 {
		return 0, fmt.Errorf("cannot find whitespace in the first line of response %q", buf)
	}
	h.noHTTP11 = !bytes.Equal(b[:n], []byte("HTTP/1.1"))
	b = b[n+1:]
	h.statusCode, n, err = parseUintBuf(b)
	if err != nil {
		return 0, fmt.Errorf("cannot parse response status code: %w. Response %q", err, buf)
	}
	if len(b) > n && b[n] != ' ' {
		return 0, fmt.Errorf("unexpected char at the end of status code. Response %q", buf)
	}
	return len(buf) - len(bNext), nil
}

func parseUintBuf(b []byte) (int, int, error) {
	n := len(b)
	if n == 0 {
		return -1, 0, errEmptyInt
	}
	v := 0
	for i := 0; i < n; i++ {
		c := b[i]
		k := c - '0'
		if k > 9 {
			if i == 0 {
				return -1, i, errUnexpectedFirstChar
			}
			return v, i, nil
		}
		vNew := 10*v + int(k)
		if vNew < v {
			return -1, i, errTooLongInt
		}
		v = vNew
	}
	return v, n, nil
}

func parseContentLength(b []byte) (int, error) {
	v, n, err := parseUintBuf(b)
	if err != nil {
		return -1, fmt.Errorf("cannot parse Content-Length: %w", err)
	}
	if n != len(b) {
		return -1, fmt.Errorf("cannot parse Content-Length: non-numeric chars found")
	}
	return v, nil
}

func isTokenByte(c byte) bool {
	if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' {
		return true
	}
	switch c {
	case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
		return true
	}
	return false
}

func validHeaderValueByte(c byte) bool {
	if c >= 0x80 {
		return true
	}
	if c == '\t' || c == ' ' {
		return true
	}
	return c >= 0x21 && c <= 0x7e
}

func isWS(c byte) bool { return c == ' ' || c == '\t' }

func trimWS(b []byte) []byte {
	for len(b) > 0 && isWS(b[0]) {
		b = b[1:]
	}
	for len(b) > 0 && isWS(b[len(b)-1]) {
		b = b[:len(b)-1]
	}
	return b
}

func trimRightWS(b []byte) []byte {
	for len(b) > 0 && isWS(b[len(b)-1]) {
		b = b[:len(b)-1]
	}
	return b
}

