	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"syscall"
)

var hex2int [256]byte

func init() {
	for i := range hex2int {
		hex2int[i] = 16
	}
	for c := '0'; c <= '9'; c++ {
		hex2int[c] = byte(c - '0')
	}
	for c := 'a'; c <= 'f'; c++ {
		hex2int[c] = byte(c - 'a' + 10)
	}
	for c := 'A'; c <= 'F'; c++ {
		hex2int[c] = byte(c - 'A' + 10)
	}
}

func isConnectionReset(err error) bool {
	return errors.Is(err, syscall.ECONNRESET)
}

func readResponseBody(h *responseHeader, r *bufio.Reader, maxBodySize int) ([]byte, error) {
	cl := h.contentLength
	if cl >= 0 {
		if maxBodySize > 0 && cl > maxBodySize {
			return nil, errBodyTooLarge
		}
		return appendBodyFixedSize(r, nil, cl)
	} else if cl == -1 {
		b, err := readBodyChunked(r, maxBodySize)
		if err != nil {
			return b, err
		}
		if err := readTrailer(r); err != nil && err != io.EOF {
			return b, err
		}
		return b, nil
	}
	return readBodyIdentity(r, maxBodySize)
}

func appendBodyFixedSize(r *bufio.Reader, dst []byte, n int) ([]byte, error) {
	if n == 0 {
		return dst, nil
	}
	offset := len(dst)
	dstLen := offset + n
	if cap(dst) < dstLen {
		b := make([]byte, dstLen)
		copy(b, dst)
		dst = b
	}
	dst = dst[:dstLen]
	for {
		nn, err := r.Read(dst[offset:])
		if nn <= 0 {
			switch {
			case errors.Is(err, io.EOF):
				return dst[:offset], io.ErrUnexpectedEOF
			case err != nil:
				return dst[:offset], err
			default:
				return dst[:offset], fmt.Errorf("bufio.Read() returned (%d, nil)", nn)
			}
		}
		offset += nn
		if offset == dstLen {
			return dst, nil
		}
	}
}

func readBodyIdentity(r *bufio.Reader, maxBodySize int) ([]byte, error) {
	dst := make([]byte, 1024)
	offset := 0
	for {
		nn, err := r.Read(dst[offset:])
		if nn <= 0 {
			switch {
			case errors.Is(err, io.EOF):
				return dst[:offset], nil
			case err != nil:
				return dst[:offset], err
			default:
				return dst[:offset], fmt.Errorf("bufio.Read() returned (%d, nil)", nn)
			}
		}
		offset += nn
		if maxBodySize > 0 && offset > maxBodySize {
			return dst[:offset], errBodyTooLarge
		}
		if len(dst) == offset {
			n := 2 * offset
			if maxBodySize > 0 && n > maxBodySize {
				n = maxBodySize + 1
			}
			b := make([]byte, n)
			copy(b, dst)
			dst = b
		}
	}
}

func readBodyChunked(r *bufio.Reader, maxBodySize int) ([]byte, error) {
	var dst []byte
	for {
		chunkSize, err := parseChunkSize(r)
		if err != nil {
			return dst, err
		}
		if chunkSize == 0 {
			return dst, nil
		}
		if maxBodySize > 0 && len(dst)+chunkSize > maxBodySize {
			return dst, errBodyTooLarge
		}
		dst, err = appendBodyFixedSize(r, dst, chunkSize+2)
		if err != nil {
			return dst, err
		}
		if !bytes.Equal(dst[len(dst)-2:], []byte("\r\n")) {
			return dst, errors.New("cannot find crlf at the end of chunk")
		}
