		}
		if i >= 15 {
			return -1, errTooLargeHexNum
		}
		n = (n << 4) | k
		i++
	}
}

// readTrailer reads (and discards) chunked trailers.
func readTrailer(r *bufio.Reader) error {
	n := 1
	for {
		b, err := r.Peek(n)
		if len(b) == 0 {
			if n == 1 || err == io.EOF {
