		if len(b) >= 1 && b[0] == '\n' {
			r.Discard(1)
			return nil
		}
		idx := bytes.Index(b, []byte("\r\n\r\n"))
		if idx >= 0 {
			r.Discard(idx + 4)
			return nil
		}
		if err != nil {
			return err
		}
		n = r.Buffered() + 1
	}
