var errDialTimeout = errors.New("dialing to the given TCP address timed out")

const defaultDialTimeout = 3 * time.Second

type dialError struct {
	upstream string
	err      error
}

func (e *dialError) Error() string {
	return "error when dialing " + e.upstream + ": " + e.err.Error()
}

func (e *dialError) Unwrap() error { return e.err }

type tcpAddrEntry struct {
	addrs []net.TCPAddr
	idx   uint32
	time  time.Time
}

type tcpDialer struct {
	resolver *net.Resolver
	mu       sync.Mutex
	cache    map[string]*tcpAddrEntry
}

func newTCPDialer(resolver *net.Resolver) *tcpDialer {
	if resolver == nil {
		resolver = net.DefaultResolver
	}
	return &tcpDialer{resolver: resolver, cache: map[string]*tcpAddrEntry{}}
}

func (d *tcpDialer) getTCPAddrs(addr string, dualStack bool, deadline time.Time) ([]net.TCPAddr, uint32, error) {
	d.mu.Lock()
	e := d.cache[addr]
	if e != nil && time.Since(e.time) > time.Minute {
		e = nil
	}
	d.mu.Unlock()

	if e == nil {
		addrs, err := resolveTCPAddrs(addr, dualStack, d.resolver, deadline)
		if err != nil {
			return nil, 0, err
		}
		e = &tcpAddrEntry{addrs: addrs, time: time.Now()}
		d.mu.Lock()
		d.cache[addr] = e
		d.mu.Unlock()
	}

	d.mu.Lock()
	e.idx++
	idx := e.idx
	d.mu.Unlock()
	return e.addrs, idx, nil
}

func resolveTCPAddrs(addr string, dualStack bool, resolver *net.Resolver, deadline time.Time) ([]net.TCPAddr, error) {
	host, portS, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}
	port, err := strconv.Atoi(portS)
	if err != nil {
		return nil, err
	}
	ctx, cancel := context.WithDeadline(context.Background(), deadline)
	defer cancel()
	ipaddrs, err := resolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	addrs := make([]net.TCPAddr, 0, len(ipaddrs))
	for _, ip := range ipaddrs {
		if !dualStack && ip.IP.To4() == nil {
			continue
		}
		addrs = append(addrs, net.TCPAddr{IP: ip.IP, Port: port, Zone: ip.Zone})
	}
	if len(addrs) == 0 {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	return addrs, nil
}

func (d *tcpDialer) dial(addr string, dualStack bool, timeout time.Duration) (net.Conn, error) {
	deadline := time.Now().Add(timeout)
	addrs, idx, err := d.getTCPAddrs(addr, dualStack, deadline)
	if err != nil {
		return nil, err
	}
	network := "tcp4"
	if dualStack {
		network = "tcp"
	}
	var conn net.Conn
	n := uint32(len(addrs))
	for i := uint32(0); i < n; i++ {
		conn, err = tryDial(network, &addrs[(idx+i)%n], deadline)
		if err == nil {
			return conn, nil
		}
		if errors.Is(err, errDialTimeout) {
			return nil, err
		}
	}
	return nil, err
}

func tryDial(network string, addr *net.TCPAddr, deadline time.Time) (net.Conn, error) {
	if time.Until(deadline) <= 0 {
		return nil, &dialError{addr.String(), errDialTimeout}
	}
	ctx, cancel := context.WithDeadline(context.Background(), deadline)
	defer cancel()
	var dialer net.Dialer
	conn, err := dialer.DialContext(ctx, network, addr.String())
	if err != nil && ctx.Err() == context.DeadlineExceeded {
		return nil, &dialError{addr.String(), errDialTimeout}
	}
	if err != nil {
		return nil, &dialError{addr.String(), err}
	}
	return conn, nil
}

// fhRequest holds the data needed to serialize a request.
type fhRequest struct {
	u          *url.URL
	userAgent  string
	ctype      string
	clength    string
	headers    []headerKV
	cookies    []cookieKV
	connClose  bool
	hasAuthHdr bool
}

type cookieKV struct {
	key   string
	value string
}

func parseRequestCookies(cookies []cookieKV, src string) []cookieKV {
	b := src
	for len(b) > 0 {
		var kv cookieKV
		isKey := true
		k := 0
		end := len(b)
		rest := ""
		for i := 0; i < len(b); i++ {
			c := b[i]
			if c == '=' && isKey {
				isKey = false
				kv.key = trimCookieArg(b[:i], false)
				k = i + 1
			} else if c == ';' {
				end = i
				rest = b[i+1:]
				break
			}
		}
		if isKey {
			kv.key = ""
		}
		kv.value = trimCookieArg(b[k:end], true)
		if end == len(b) {
			rest = ""
		}
		if len(kv.key) > 0 || len(kv.value) > 0 {
			cookies = append(cookies, kv)
		}
		b = rest
	}
	return cookies
}

func trimCookieArg(s string, skipQuotes bool) string {
	for len(s) > 0 && s[0] == ' ' {
		s = s[1:]
	}
	for len(s) > 0 && s[len(s)-1] == ' ' {
		s = s[:len(s)-1]
	}
	if skipQuotes && len(s) > 1 && s[0] == '"' && s[len(s)-1] == '"' {
		s = s[1 : len(s)-1]
	}
	return s
}

func (r *fhRequest) add(key, value string) {
	k := normalizeHeaderKeyString(key)
	switch k {
	case "User-Agent":
		r.userAgent = value
		return
	case "Host":
		return
	case "Content-Type":
		r.ctype = value
		return
	case "Content-Length":
		r.clength = value
		return
	case "Cookie":
		r.cookies = parseRequestCookies(r.cookies, value)
		return
	case "Connection":
		if value == "close" {
			r.connClose = true
			return
		}
		r.connClose = false
	case "Authorization":
		r.hasAuthHdr = true
	}
	r.headers = append(r.headers, headerKV{k, value})
}

func requestURI(u *url.URL) string {
	s := u.EscapedPath()
	if u.RawQuery != "" {
		s += "?" + u.RawQuery
	}
	return s
}

func (r *fhRequest) bytes(host string) []byte {
	var b strings.Builder
	uri := requestURI(r.u)
	if uri == "" {
		uri = "/"
	}
	b.WriteString("GET ")
	b.WriteString(uri)
	b.WriteString(" HTTP/1.1\r\n")
	if r.userAgent != "" {
		b.WriteString("User-Agent: " + r.userAgent + "\r\n")
	}
	if host != "" {
		b.WriteString("Host: " + host + "\r\n")
	}
	if r.ctype != "" {
		b.WriteString("Content-Type: " + r.ctype + "\r\n")
	}
	if r.clength != "" {
		b.WriteString("Content-Length: " + r.clength + "\r\n")
	}
	for _, kv := range r.headers {
		b.WriteString(kv.key + ": " + kv.value + "\r\n")
	}
	if r.u.User != nil && !r.hasAuthHdr {
		user := r.u.User.Username()
		pass, _ := r.u.User.Password()
		b.WriteString("Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(user+":"+pass)) + "\r\n")
	}
	if len(r.cookies) > 0 {
		b.WriteString("Cookie: ")
		for i, c := range r.cookies {
			if c.key != "" {
				b.WriteString(c.key + "=")
			}
			b.WriteString(c.value)
			if i+1 < len(r.cookies) {
				b.WriteString("; ")
			}
		}
		b.WriteString("\r\n")
	}
	if r.connClose {
		b.WriteString("Connection: close\r\n")
	}
	b.WriteString("\r\n")
	return []byte(b.String())
}

type fhResponse struct {
	header responseHeader
	body   []byte
}

type fhClient struct {
	readBufferSize      int
	maxResponseBodySize int
	skipTLSVerification bool
	dialer              *tcpDialer
	proxyDialer         *tcpDialer
	proxy               string
	sessionCache        tls.ClientSessionCache
}

func addMissingPort(addr string, isTLS bool) string {
	n := len(addr)
	if n == 0 {
		return addr
	}
	if addr[0] == '[' {
		if addr[n-1] != ']' {
			return addr
		}
	} else if strings.LastIndexByte(addr, ':') > 0 {
		return addr
	}
	if isTLS {
		return addr + ":443"
	}
	return addr + ":80"
}

func tlsServerName(addr string) string {
	if !strings.Contains(addr, ":") {
		return addr
	}
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return "*"
	}
	return host
}

func (c *fhClient) dialAddr(addr string) (net.Conn, error) {
	if c.proxy != "" {
		return c.dialProxy(addr)
	}
	return c.dialer.dial(addr, true, defaultDialTimeout)
}

func (c *fhClient) dialProxy(addr string) (net.Conn, error) {
	proxy := c.proxy
	if i := strings.Index(proxy, "://"); i >= 0 {
		proxy = proxy[i+3:]
	}
	var auth string
	if strings.Contains(proxy, "@") {
		i := strings.LastIndex(proxy, "@")
		auth = base64.StdEncoding.EncodeToString([]byte(proxy[:i]))
		proxy = proxy[i+1:]
	}
	conn, err := c.proxyDialer.dial(addMissingPort(proxy, false), false, defaultDialTimeout)
	if err != nil {
		return nil, err
	}
	req := "CONNECT " + addr + " HTTP/1.1\r\nHost: " + addr + "\r\n"
	if auth != "" {
		req += "Proxy-Authorization: Basic " + auth + "\r\n"
	}
	req += "\r\n"
	if _, err := conn.Write([]byte(req)); err != nil {
		conn.Close()
		return nil, err
	}
	var h responseHeader
	br := bufio.NewReader(conn)
	if err := readResponseHeader(&h, br); err != nil {
		conn.Close()
		return nil, err
	}
	if h.StatusCode() != 200 {
		conn.Close()
		return nil, fmt.Errorf("could not connect to proxyAddr: %s status code: %d", proxy, h.StatusCode())
	}
	return conn, nil
}

func (c *fhClient) Do(req *fhRequest, timeout time.Duration) (*fhResponse, error) {
	u := req.u
	isTLS := false
	switch u.Scheme {
	case "https":
		isTLS = true
	case "http":
	default:
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", u.Scheme)
	}
	host := strings.ToLower(u.Host)
	deadline := time.Now().Add(timeout)
	attempts := 0
	var resp *fhResponse
	var err error
	var retry bool
	for {
		if time.Until(deadline) <= 0 {
			err = errTimeout
			break
		}
		resp, retry, err = c.doOnce(req, host, isTLS, deadline)
		if err == nil || !retry {
			break
		}
		attempts++
		if attempts >= 5 {
			break
		}
	}
	if err == io.EOF {
		err = errConnectionClosed
	}
	return resp, err
}

func (c *fhClient) doOnce(req *fhRequest, host string, isTLS bool, deadline time.Time) (*fhResponse, bool, error) {
	addr := addMissingPort(host, isTLS)
	conn, err := c.dialAddr(addr)
	if err != nil {
		return nil, false, err
	}
	defer conn.Close()
	if isTLS {
		conn = tls.Client(conn, &tls.Config{
			ServerName:         tlsServerName(addr),
			InsecureSkipVerify: c.skipTLSVerification,
			ClientSessionCache: c.sessionCache,
		})
	}
	if err := conn.SetDeadline(deadline); err != nil {
		return nil, true, err
	}
	if _, err := conn.Write(req.bytes(host)); err != nil {
		if isTimeoutErr(err) {
			return nil, false, errTimeout
		}
		return nil, true, err
	}
	size := c.readBufferSize
	if size <= 0 {
		size = 4096
	}
	br := bufio.NewReaderSize(conn, size)
	resp := &fhResponse{}
	if err := readResponseHeader(&resp.header, br); err != nil {
		if isTimeoutErr(err) || err == errTimeout {
			return nil, false, errTimeout
		}
		return nil, true, err
	}
	if resp.header.StatusCode() == 100 {
		if err := readResponseHeader(&resp.header, br); err != nil {
			if isTimeoutErr(err) || err == errTimeout {
				return nil, false, errTimeout
			}
			return nil, true, err
		}
	}
	if !resp.header.mustSkipBody() {
		body, err := readResponseBody(&resp.header, br, c.maxResponseBodySize)
		if err != nil && !isConnectionReset(err) {
			if isTimeoutErr(err) {
				return nil, false, errTimeout
			}
			return nil, err != errBodyTooLarge, err
		}
		resp.body = body
	}
	return resp, false, nil
}
