func (p *hostThrottlerPool) Get(host string) *hostThrottler {
	p.mu <- struct{}{}
	defer func() { <-p.mu }()
	t, ok := p.throttlers[host]
	if !ok {
		t = newHostThrottler(p.maxConnections, p.rate)
		p.throttlers[host] = t
	}
	return t
}

