}

func (c *throttledHttpClient) Get(u *url.URL, header http.Header) (httpResponse, error) {
	c.connections.Request()
	defer c.connections.Release()
	t := c.pool.Get(u.Hostname())
	t.Request()
	defer t.Release()
	return c.client.Get(u, header)
}

