func (p *hostThrottlerPool) Get(host string) *hostThrottler {
	p.mu <- struct{}{}
	defer func() { <-p.mu }()
	t, ok := p.throttlers[host]
	if !ok {
		t = newHostThrottler(p.maxConnections, p.rate)
		p.throttlers[host] = t
	}
	return t
}

type throttledHttpClient struct {
	client      httpClient
	connections semaphore
	pool        *hostThrottlerPool
}

func newThrottledHttpClient(c httpClient, rate, maxConnections, maxConnectionsPerHost int) httpClient {
	return &throttledHttpClient{c, newSemaphore(maxConnections), newHostThrottlerPool(maxConnectionsPerHost, rate)}
}

func (c *throttledHttpClient) Get(u *url.URL, header http.Header) (httpResponse, error) {
	c.connections.Request()
	defer c.connections.Release()
	t := c.pool.Get(u.Hostname())
	t.Request()
	defer t.Release()
	return c.client.Get(u, header)
}

// retryHttpClient

type retryHttpClient struct {
	client     httpClient
	maxRetries int
}

func isRetryableError(err error) bool {
	return errors.Is(err, syscall.EMFILE) || errors.Is(err, syscall.ENFILE)
}

func (c *retryHttpClient) Get(u *url.URL, header http.Header) (httpResponse, error) {
	var r httpResponse
	var err error
	for i := 0; i <= c.maxRetries; i++ {
		r, err = c.client.Get(u, header)
		if err == nil || !isRetryableError(err) {
			return r, err
		}
	}
	return r, err
}

// redirectHttpClient

type redirectHttpClient struct {
	client          httpClient
	maxRedirections int
}

func (c *redirectHttpClient) Get(u *url.URL, header http.Header) (httpResponse, error) {
	jar, err := cookiejar.New(nil)
	if err != nil {
		return nil, err
	}
	header = header.Clone()
	if header == nil {
		header = http.Header{}
	}
	for i := 0; i <= c.maxRedirections; i++ {
		r, err := c.client.Get(u, header)
		if err != nil {
			if i == 0 {
				return nil, err
			}
			return nil, fmt.Errorf("%w (following redirect %v)", err, u.String())
		}
		code := r.StatusCode()
		if code < 300 || code >= 400 {
			return r, nil
		}
		loc := r.Header("Location")
		if loc == "" {
			return nil, errors.New("location header not set")
		}
		jar.SetCookies(u, parseCookies(r.Header("Set-Cookie")))
		for _, ck := range jar.Cookies(u) {
			header.Add("Cookie", ck.String())
		}
		u, err = u.Parse(loc)
		if err != nil {
			return nil, err
		}
	}
	return nil, errors.New("too many redirections")
}

func parseCookies(s string) []*http.Cookie {
	if s == "" {
		return nil
	}
	return (&http.Request{Header: http.Header{"Cookie": {s}}}).Cookies()
}

// checkedHttpClient

type checkedHttpClient struct {
	client              httpClient
	acceptedStatusCodes statusCodeSet
}

func (c *checkedHttpClient) Get(u *url.URL, header http.Header) (httpResponse, error) {
	r, err := c.client.Get(u, header)
	if err != nil {
		return nil, err
	}
	if !c.acceptedStatusCodes.Contains(r.StatusCode()) {
		return nil, errors.New(strconv.Itoa(r.StatusCode()))
	}
	return r, nil
}
