package main

import (
	"sync"
	"time"
)

// rateLimiter implements a leaky-bucket limiter with slack.
type rateLimiter struct {
	mu         sync.Mutex
	perRequest time.Duration
	maxSlack   time.Duration
	next       int64
	started    bool
}

func newRateLimiter(rate int) *rateLimiter {
	per := time.Second / time.Duration(rate)
	return &rateLimiter{perRequest: per, maxSlack: 10 * per}
}

func (l *rateLimiter) Take() {
	l.mu.Lock()
	now := time.Now().UnixNano()
	var n int64
	switch {
	case !l.started:
		n = now
		l.started = true
	case l.maxSlack > 0 && now-l.next > int64(l.maxSlack)+int64(l.perRequest):
		n = now - int64(l.maxSlack)
	default:
		n = l.next + int64(l.perRequest)
	}
	l.next = n
	l.mu.Unlock()
	if d := time.Duration(n - now); d > 0 {
		time.Sleep(d)
	}
}
