	links     map[string]error
	order     []string
}

func (p *page) URL() *url.URL                    { return p.url }
func (p *page) Fragments() map[string]struct{}   { return p.fragments }
func (p *page) Links() map[string]error          { return p.links }

type linkFilterer struct {
	excludes []*regexp.Regexp
	includes []*regexp.Regexp
}

func (f linkFilterer) IsValid(u *url.URL) bool {
	s := u.String()
	if len(f.includes) != 0 && !matchAny(s, f.includes) {
		return false
	}
	return !matchAny(s, f.excludes)
}

func matchAny(s string, rs []*regexp.Regexp) bool {
	for _, r := range rs {
		if r.MatchString(s) {
			return true
		}
	}
	return false
}

type pageParser struct {
	linkFinder linkFinder
}

func walk(n *html.Node, f func(*html.Node) bool) bool {
	if !f(n) {
		return false
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if !walk(c, f) {
			return false
		}
	}
	return true
}

func getAttr(n *html.Node, key string) (string, bool) {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val, true
		}
	}
	return "", false
}

func (pp *pageParser) Parse(rawURL *url.URL, body []byte) (*page, error) {
	n, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	u := *rawURL
	u.Fragment = ""
	u.RawFragment = ""

	base := &u
	var baseNode *html.Node
	walk(n, func(n *html.Node) bool {
		if n.Type == html.ElementNode && n.Data == "base" {
			baseNode = n
			return false
		}
		return true
	})
	if baseNode != nil {
		href, _ := getAttr(baseNode, "href")
		b, err := url.Parse(href)
		if err != nil {
			return nil, err
		}
		base = u.ResolveReference(b)
	}

	frags := map[string]struct{}{}
	walk(n, func(n *html.Node) bool {
		if n.Type == html.ElementNode {
			for _, a := range n.Attr {
				if a.Key == "id" || a.Key == "name" {
					frags[a.Val] = struct{}{}
				}
			}
		}
		return true
	})

	links, order := pp.linkFinder.Find(n, base)
	return &page{&u, frags, links, order}, nil
}

type linkFinder struct {
	filterer linkFilterer
}

var linkAttributes = map[string][]string{
	"a":      {"href"},
	"frame":  {"src"},
	"iframe": {"src"},
	"img":    {"src"},
	"link":   {"href"},
	"script": {"src"},
	"source": {"src", "srcset"},
	"track":  {"src"},
	"meta":   {"content"},
}

var metaProperties = map[string]struct{}{
	"og:image":            {},
	"og:image:url":        {},
	"og:image:secure_url": {},
	"og:audio":            {},
	"og:video":            {},
	"twitter:image":       {},
}

func parseSrcSet(s string) []string {
	ss := []string{}
	for _, part := range strings.Split(s, ", ") {
		part = strings.TrimSpace(part)
		if i := strings.LastIndexFunc(part, unicode.IsSpace); i >= 0 {
			part = part[:i]
		}
		ss = append(ss, part)
	}
	return ss
}

func (f linkFinder) Find(n *html.Node, base *url.URL) (map[string]error, []string) {
	ls := map[string]error{}
	order := []string{}
	add := func(k string, err error) {
		if _, ok := ls[k]; !ok {
			order = append(order, k)
		}
		ls[k] = err
	}
	walk(n, func(n *html.Node) bool {
		if n.Type != html.ElementNode {
			return true
		}
		attrs, ok := linkAttributes[n.Data]
		if !ok {
			return true
		}
		switch n.Data {
		case "link":
			if rel, _ := getAttr(n, "rel"); rel == "preconnect" || rel == "dns-prefetch" {
				return true
			}
		case "meta":
			p, _ := getAttr(n, "property")
			if _, ok := metaProperties[p]; !ok {
				return true
			}
		}
		for _, an := range attrs {
			v, ok := getAttr(n, an)
			if !ok {
				continue
			}
			var ss []string
			if an == "srcset" {
				ss = parseSrcSet(v)
			} else {
				ss = []string{v}
			}
			for _, s := range ss {
				s = strings.TrimSpace(s)
				if s == "" {
					continue
				}
				u, err := url.Parse(s)
				if err != nil {
					add(s, err)
					continue
				}
				u = base.ResolveReference(u)
				if u.Scheme != "http" && u.Scheme != "https" {
					continue
				}
				if !f.filterer.IsValid(u) {
					continue
				}
				add(u.String(), nil)
			}
		}
		return true
	})
	return ls, order
}
EOF
