package main

import (
	"fmt"
	"mime"
	"net/http"
	"net/url"
	"sync"
)

type fetchResult struct {
	status int
	page   *page
	err    error
}

type cacheEntry struct {
	done   chan struct{}
	result fetchResult
}

type linkFetcherOptions struct {
	Header          http.Header
	IgnoreFragments bool
}

type linkFetcher struct {
	client     httpClient
	pageParser *pageParser
	options    linkFetcherOptions
	mu         sync.Mutex
	cache      map[string]*cacheEntry
}

func newLinkFetcher(c httpClient, pp *pageParser, o linkFetcherOptions) *linkFetcher {
	return &linkFetcher{client: c, pageParser: pp, options: o, cache: map[string]*cacheEntry{}}
}

func (f *linkFetcher) Fetch(s string) (int, *page, error) {
	s, fragment, err := separateFragment(s)
	if err != nil {
		return 0, nil, err
	}
	r := f.sendRequestWithCache(s)
	if r.err != nil {
		return 0, nil, r.err
	}
	if r.page != nil && fragment != "" && !f.options.IgnoreFragments {
		if _, ok := r.page.Fragments()[fragment]; !ok {
			return 0, nil, fmt.Errorf("id #%v not found", fragment)
		}
	}
	return r.status, r.page, nil
}

func (f *linkFetcher) sendRequestWithCache(s string) fetchResult {
	f.mu.Lock()
	e, ok := f.cache[s]
	if ok {
		f.mu.Unlock()
		<-e.done
		return e.result
	}
	e = &cacheEntry{done: make(chan struct{})}
	f.cache[s] = e
	f.mu.Unlock()
	e.result = f.sendRequest(s)
	close(e.done)
	return e.result
}

func (f *linkFetcher) sendRequest(s string) fetchResult {
	u, err := url.Parse(s)
	if err != nil {
		return fetchResult{err: err}
	}
	r, err := f.client.Get(u, f.options.Header)
	if err != nil {
		return fetchResult{err: err}
	}
	t, _, err := mime.ParseMediaType(r.Header("Content-Type"))
	if err != nil {
		return fetchResult{err: err}
	}
	if t != "text/html" {
		return fetchResult{status: r.StatusCode()}
	}
	p, err := f.pageParser.Parse(r.URL(), r.Body())
	if err != nil {
		return fetchResult{err: err}
	}
	return fetchResult{status: r.StatusCode(), page: p}
}

func separateFragment(s string) (string, string, error) {
	u, err := url.Parse(s)
	if err != nil {
		return "", "", err
	}
	f := u.Fragment
	u.Fragment = ""
	u.RawFragment = ""
	return u.String(), f, nil
}
EOF
