	args []string
}

func (s *parseState) eof() bool { return len(s.args) == 0 }
func (s *parseState) pop() string {
	a := s.args[0]
	s.args = s.args[1:]
	return a
}

func unquoteIfPossible(s string) (string, error) {
	if len(s) < 2 || s[0] != '"' {
		return s, nil
	}
	return strconv.Unquote(s)
}

func parseOption(s *parseState, o *optionDef, canarg bool, argument *string) error {
	var err error
	if !o.canArgument() {
		if argument != nil {
			return newFlagError("bool flag `%s' cannot have an argument", o)
		}
		err = o.set(nil)
	} else if argument != nil || (canarg && !s.eof()) {
		var arg string
		if argument != nil {
			arg = *argument
		} else {
			arg = s.pop()
			if verr := o.isValidValue(arg); verr != nil {
				return newFlagError("%s", verr.Error())
			} else if arg == "--" {
				return newFlagError("expected argument for flag `%s', but got double dash `--'", o)
			}
		}
		arg, err = unquoteIfPossible(arg)
		if err == nil {
			err = o.set(&arg)
		}
	} else {
		err = newFlagError("expected argument for flag `%s'", o)
	}
	if err != nil {
		if _, ok := err.(*flagError); !ok {
			err = o.marshalError(err)
		}
	}
	return err
}

func parseArguments(args []string) (*arguments, error) {
	a := &arguments{}
	defs := a.optionDefs()
	setDefaults(defs)
	shorts := map[byte]*optionDef{}
	longs := map[string]*optionDef{}
	for _, o := range defs {
		if o.short != 0 {
			shorts[o.short] = o
		}
		longs[o.long] = o
	}

	s := &parseState{args: args}
	for !s.eof() {
		arg := s.pop()
		if arg == "--" {
			a.positional = append(a.positional, s.args...)
			break
		}
		if !argumentIsOption(arg) {
			a.positional = append(a.positional, arg)
			continue
		}
		var prefixLen int
		islong := false
		if strings.HasPrefix(arg, "--") {
			prefixLen = 2
			islong = true
		} else {
			prefixLen = 1
		}
		optname := arg[prefixLen:]
		var argument *string
		pos := strings.Index(optname, "=")
		if (islong && pos >= 0) || (!islong && pos == 1) {
			rest := optname[pos+1:]
			argument = &rest
			optname = optname[:pos]
		}
		var err error
		if islong {
			o, ok := longs[optname]
			if !ok {
				err = newFlagError("unknown flag `%s'", optname)
			} else {
				err = parseOption(s, o, true, argument)
			}
		} else {
			err = parseShort(s, shorts, optname, argument)
		}
		if err != nil {
			return a, err
		}
	}
	return a, nil
}

func parseShort(s *parseState, shorts map[byte]*optionDef, optname string, argument *string) error {
	if argument == nil && len(optname) > 1 {
		if o, ok := shorts[optname[0]]; ok && o.canArgument() {
			rest := optname[1:]
			argument = &rest
			optname = optname[:1]
		}
	}
	for i := 0; i < len(optname); i++ {
		c := optname[i]
		o, ok := shorts[c]
		if !ok {
			// emulate rune handling
			r := []rune(optname[i:])
			return newFlagError("unknown flag `%s'", string(r[0]))
		}
		canarg := i+1 == len(optname)
		if err := parseOption(s, o, canarg, argument); err != nil {
			return err
		}
		argument = nil
	}
	return nil
}

// help

type winsize struct {
	row, col, xpixel, ypixel uint16
}

func terminalColumns() int {
	ws := winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(0), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	c := int(ws.col)
	if c <= 0 {
		c = 80
	}
	return c
}

func wrapText(s string, l int, prefix string) string {
	var ret string
	if l < 10 {
		l = 10
	}
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		var retline string
		line = strings.TrimSpace(line)
		for len(line) > l {
			suffix := ""
			pos := strings.LastIndex(line[:l], " ")
			if pos < 0 {
				pos = l - 1
				suffix = "-\n"
			}
			if len(retline) != 0 {
				retline += "\n" + prefix
			}
			retline += strings.TrimSpace(line[:pos]) + suffix
			line = strings.TrimSpace(line[pos:])
		}
		if len(line) > 0 {
			if len(retline) != 0 {
				retline += "\n" + prefix
			}
			retline += line
		}
		if len(ret) > 0 {
			ret += "\n"
			if len(retline) > 0 {
				ret += prefix
			}
		}
		ret += retline
	}
	return ret
}

func helpText(a *arguments) string {
	cols := terminalColumns()
	const descstart = 44
	var b strings.Builder
	b.WriteString("Usage:\n")
	b.WriteString("  " + path.Base(os.Args[0]) + " [options] <url>\n\n")
	b.WriteString("Application Options:\n")
	for _, o := range a.optionDefs() {
		var line strings.Builder
		line.WriteString("  ")
		if o.short != 0 {
			line.WriteString("-" + string(o.short))
		} else {
			line.WriteString("  ")
		}
		if o.short != 0 {
			line.WriteString(", ")
		} else {
			line.WriteString("  ")
		}
		line.WriteString("--" + o.long)
		if o.canArgument() {
			line.WriteString("=")
			line.WriteString(o.valueName)
			if len(o.choices) > 0 {
				line.WriteString("[" + strings.Join(o.choices, "|") + "]")
			}
		}
		written := line.Len()
		b.WriteString(line.String())
		dw := descstart - written
		if dw > 0 {
			b.WriteString(strings.Repeat(" ", dw))
		}
		desc := o.desc
		if o.def != "" {
			desc = fmt.Sprintf("%s (default: %v)", o.desc, o.def)
		}
		b.WriteString(wrapText(desc, cols-descstart, strings.Repeat(" ", descstart)))
		b.WriteString("\n")
	}
	return b.String()
}

var errHelp = errors.New("help")
EOF
