package main

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"regexp"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

const version = "2.11.1"

type command struct {
	stdout   io.Writer
	stderr   io.Writer
	stdoutTTY bool
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func (c *command) Run(args []string) bool {
	ok, err := c.runWithError(args)
	if err != nil {
		fmt.Fprintln(c.stderr, colorizer{c.stdoutTTY}.Red(err.Error()))
		return false
	}
	return ok
}

func compileRegexps(ss []string) ([]*regexp.Regexp, error) {
	rs := make([]*regexp.Regexp, 0, len(ss))
	for _, s := range ss {
		r, err := regexp.Compile(s)
		if err != nil {
			return nil, err
		}
		rs = append(rs, r)
	}
	return rs, nil
}

func parseRawHeaders(ss []string) (http.Header, error) {
	h := http.Header{}
	for _, s := range ss {
		i := strings.Index(s, ":")
		if i < 0 {
			return nil, errors.New("invalid header format")
		}
		h.Add(s[:i], strings.TrimSpace(s[i+1:]))
	}
	return h, nil
}

func (c *command) runWithError(rawArgs []string) (bool, error) {
	args, err := parseArguments(rawArgs)
	if err != nil {
		return false, err
	}
	if args.Help {
		fmt.Fprint(c.stdout, helpText(args))
		return true, nil
	}
	if args.Version {
		fmt.Fprintln(c.stdout, version)
		return true, nil
	}
	if len(args.positional) != 1 {
		return false, errors.New("invalid number of arguments")
	}
	codes, err := parseStatusCodeSet(args.AcceptedStatusCodes)
	if err != nil {
		return false, err
	}
	excludes, err := compileRegexps(args.RawExcludedPatterns)
	if err != nil {
		return false, err
	}
	includes, err := compileRegexps(args.RawIncludedPatterns)
	if err != nil {
		return false, err
	}
	header, err := parseRawHeaders(args.RawHeaders)
	if err != nil {
		return false, err
	}
	format := args.Format
	if args.JSONOutput {
		format = "json"
	} else if args.JUnitOutput {
		format = "junit"
	}
	if format == "junit" && args.Verbose {
		return false, errors.New("verbose option not supported for JUnit output")
	}
	verbose := args.Verbose || (args.JSONOutput && args.VerboseJSON)

	if _, ok := header["Accept"]; !ok {
		header.Set("Accept", "*/*")
	}

	var resolver *net.Resolver
	if args.DnsResolver != "" {
		addr := args.DnsResolver
		resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
