func splitHostURI(uri string) (string, string, string) {
	n := strings.Index(uri, "//")
	if n < 0 {
		return "http", "", uri
	}
	scheme := uri[:n]
	if strings.IndexByte(scheme, '/') >= 0 {
		return "http", "", uri
	}
	if len(scheme) > 0 && scheme[len(scheme)-1] == ':' {
		scheme = scheme[:len(scheme)-1]
	}
	n += 2
	uri = uri[n:]
	n = strings.IndexByte(uri, '/')
	nq := strings.IndexByte(uri, '?')
	if nq >= 0 && (n < 0 || nq < n) {
		n = nq
	} else if n < 0 {
		return scheme, uri, "/"
	}
	return scheme, uri[:n], uri[n:]
}

func parseFastURI(s string) *fastURI {
	u := &fastURI{}
	scheme, host, uri := splitHostURI(s)
	u.scheme = strings.ToLower(scheme)
	if n := strings.IndexByte(host, '@'); n >= 0 {
		auth := host[:n]
		host = host[n+1:]
		u.hasAuth = true
		if m := strings.IndexByte(auth, ':'); m >= 0 {
