		host = h
	}
	u.host = strings.ToLower(host)

	qi := strings.IndexByte(uri, '?')
	fi := strings.IndexByte(uri, '#')
	if fi >= 0 && qi > fi {
		qi = -1
	}
	var path, query string
	switch {
	case qi < 0 && fi < 0:
		path = uri
	case qi >= 0:
		path = uri[:qi]
