func decodeBrotli(b []byte) ([]byte, error) {
	var out *C.uint8_t
	var outLen C.size_t
	var errname *C.char
	var in *C.uint8_t
	if len(b) > 0 {
		in = (*C.uint8_t)(unsafe.Pointer(&b[0]))
	}
	r := C.brotli_decode(in, C.size_t(len(b)), &out, &outLen, &errname)
	var data []byte
	if out != nil {
		data = C.GoBytes(unsafe.Pointer(out), C.int(outLen))
		C.free(unsafe.Pointer(out))
	}
	switch r {
	case 1:
		return data, nil
	case 2:
		return nil, io.ErrUnexpectedEOF
	case 0:
		name := C.GoString(errname)
		for _, p := range []string{"_ERROR_FORMAT_", "_ERROR_ALLOC_", "_ERROR_", "_"} {
			if strings.HasPrefix(name, p) {
				name = name[len(p):]
				break
			}
		}
		return nil, errors.New("brotli: " + name)
	}
	return b, nil
}
